# a lone sentence written as t('...') has no children: show it as a plain note box instead of an empty label
def _fix(nodes):
    out = []
    for n in nodes:
        if n[0] == 'tree' and not n[2]: n = ('bx', 'bl', n[1])
        elif n[0] == 'two': n = ('two', _fix([n[1]])[0], _fix([n[2]])[0])
        out.append(n)
    return out
for _c in CHS: _c['nodes'] = _fix(_c['nodes'])
